package com.example.leetcodetrainer.curriculum.controller;
import com.example.leetcodetrainer.curriculum.service.CurriculumFoundationService; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.GetMapping;
@Controller public class CurriculumFoundationController { private final CurriculumFoundationService service; public CurriculumFoundationController(CurriculumFoundationService s){service=s;} @GetMapping("/curriculum") public String coverage(Model m){m.addAttribute("skills",service.skills());m.addAttribute("modes",service.modes());m.addAttribute("requirements",service.requirements());m.addAttribute("items",service.items());m.addAttribute("exposures",service.exposures());m.addAttribute("sessions",service.sessions());m.addAttribute("coverageByRole",service.coverageByRole());m.addAttribute("coverageByPattern",service.coverageByPattern());return "curriculum/coverage";} }
